PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS crane_models (id TEXT PRIMARY KEY, manufacturer TEXT NOT NULL, model_name TEXT NOT NULL, crane_type TEXT NOT NULL CHECK(crane_type IN ('TRUCK','ALL_TERRAIN')));
CREATE TABLE IF NOT EXISTS crane_units (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES crane_models(id), serial_number TEXT NOT NULL UNIQUE, registration TEXT);
CREATE TABLE IF NOT EXISTS chart_documents (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES crane_models(id), source TEXT NOT NULL, version TEXT NOT NULL, sha256 TEXT NOT NULL, is_fictional INTEGER NOT NULL DEFAULT 1 CHECK(is_fictional IN (0,1)), verified_by TEXT, verified_at TEXT, approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN (0,1)), CHECK(approved=0 OR (verified_by IS NOT NULL AND verified_at IS NOT NULL)));
CREATE TABLE IF NOT EXISTS crane_configurations (id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES crane_models(id), counterweight_kg REAL NOT NULL CHECK(counterweight_kg>=0), outrigger_span_mm REAL NOT NULL CHECK(outrigger_span_mm>0), boom_length_mm REAL NOT NULL CHECK(boom_length_mm>0), sector TEXT NOT NULL, attachments TEXT NOT NULL, support TEXT NOT NULL CHECK(support='OUTRIGGERS'));
CREATE TABLE IF NOT EXISTS load_chart_tables (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES chart_documents(id), configuration_id TEXT NOT NULL REFERENCES crane_configurations(id), original_page TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0));
CREATE TABLE IF NOT EXISTS load_chart_entries (id TEXT PRIMARY KEY, table_id TEXT NOT NULL REFERENCES load_chart_tables(id), radius_mm REAL NOT NULL CHECK(radius_mm>0), capacity_kg REAL CHECK(capacity_kg>0), prohibited INTEGER NOT NULL DEFAULT 0 CHECK(prohibited IN (0,1)), UNIQUE(table_id,radius_mm));
CREATE TABLE IF NOT EXISTS load_chart_notes (id TEXT PRIMARY KEY, table_id TEXT NOT NULL REFERENCES load_chart_tables(id), original_page TEXT NOT NULL, note_text TEXT NOT NULL, deduction_rule TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS load_chart_reviews (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES chart_documents(id), reviewer TEXT NOT NULL, reviewed_at TEXT NOT NULL, decision TEXT NOT NULL CHECK(decision IN ('VERIFIED','APPROVED','REJECTED')), source_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lift_plans (id TEXT PRIMARY KEY, plan_number TEXT NOT NULL, title TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), status TEXT NOT NULL CHECK(status IN ('DRAFT','UNDER_REVIEW','APPROVED','SUPERSEDED')), supersedes_id TEXT REFERENCES lift_plans(id), UNIQUE(plan_number,revision));
CREATE TABLE IF NOT EXISTS lift_cases (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES lift_plans(id), unit_id TEXT REFERENCES crane_units(id), configuration_id TEXT REFERENCES crane_configurations(id), chart_table_id TEXT REFERENCES load_chart_tables(id), radius_mm REAL CHECK(radius_mm>0), object_weight_kg REAL CHECK(object_weight_kg>=0), hook_weight_kg REAL CHECK(hook_weight_kg>=0), deductions_kg REAL CHECK(deductions_kg>=0), outrigger_reaction_n REAL CHECK(outrigger_reaction_n>=0), ground_allowable_pa REAL CHECK(ground_allowable_pa>0), pad_area_mm2 REAL CHECK(pad_area_mm2>0));
CREATE TABLE IF NOT EXISTS rigging_components (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES lift_cases(id), description TEXT NOT NULL, weight_kg REAL CHECK(weight_kg>=0), wll_kg REAL CHECK(wll_kg>0), angle_rad REAL CHECK(angle_rad>=0 AND angle_rad<=3.141592653589793), source TEXT);
CREATE TABLE IF NOT EXISTS lift_checks (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES lift_cases(id), check_type TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','INSUFFICIENT_DATA','NOT_APPLICABLE')), reason TEXT NOT NULL, plan_revision INTEGER NOT NULL, chart_revision INTEGER, input_snapshot TEXT NOT NULL, checked_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_records (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES lift_plans(id), reviewer TEXT NOT NULL, reviewed_at TEXT NOT NULL, decision TEXT NOT NULL, comments TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, plan_id TEXT REFERENCES lift_plans(id), document_id TEXT REFERENCES chart_documents(id), filename TEXT NOT NULL, storage_key TEXT NOT NULL, sha256 TEXT NOT NULL, CHECK(plan_id IS NOT NULL OR document_id IS NOT NULL));
CREATE TRIGGER IF NOT EXISTS approved_plan_no_update BEFORE UPDATE ON lift_plans WHEN OLD.status IN ('APPROVED','SUPERSEDED') BEGIN SELECT RAISE(ABORT,'immutable approved plan'); END;
CREATE TRIGGER IF NOT EXISTS approved_plan_no_delete BEFORE DELETE ON lift_plans WHEN OLD.status IN ('APPROVED','SUPERSEDED') BEGIN SELECT RAISE(ABORT,'immutable approved plan'); END;
